      SUBROUTINE MRECCC     RESTORES RC2 TO VALUES AT BEGINNING OF FITTED SECTIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RCPS.CIN'      INCLUDE 'RCS.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RC2S.CIN'      INCLUDE 'RSS.CIN'      INCLUDE 'R0P.CIN'      INCLUDE 'R0PS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R2PS.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC2S.CIN'      INCLUDE 'TSS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC2S.CIN'CC------------------------------------------------------------------      R0P = R0PS      DO 10 J = 1, 36      RL(J) = RSSL(J)      RCL(J) = RCSL(J)   10 RC2L(J) = RC2SL(J)      RCP = RCPS      IF (NORD1 .GE. 2) THEN        DO 20 J = 1, 105        TL(J) = TSSL(J)   20   TC2L(J) = TC2SL(J)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 J = 1, 280   30   UC2L(J) = UC2SL(J)      ENDIF      R2P = R2PS      R3P = .FALSE.      RETURN      END